INSERT INTO `faq_items` (`faq_id`, `category_id`, `question`, `answer`, `youtube_tutorial_url`, `youtube_thumbnail_url`, `youtube_video_id`, `is_featured`, `is_active`, `delete_flag`, `view_count`, `sort_order`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 2, 'What is Daily Hisab App ?', 'Daily Hisab is a simple business calculator for every vyapari,small businesses and personal use.You can add income and expense transactions, manage categories, view reports, and track your business finances easily.', '', '', '', 1, 1, 0, 0, 1, NULL, '2025-09-25 10:13:00', '2026-02-14 13:25:16'),
(2, 2, 'How to add income and expense entries?', 'To add income or expense entries: 1) Open the app 2) Tap the + button 3) Select Income or Expense 4) Enter amount and details 5) Choose category 6) Save the entry', '', '', '', 0, 1, 0, 0, 2, NULL, '2025-09-25 10:13:00', '2026-02-14 13:26:56'),
(3, 5, 'How to edit or delete transactions?', 'To edit or delete transactions: 1) Go to the transaction list 2) Tap on the transaction you want to modify 3) Tap Edit or Delete 4) Make changes and save', '', '', '', 0, 1, 0, 0, 3, NULL, '2025-09-25 10:13:00', '2026-02-14 13:27:25'),
(4, 3, 'How to view daily or monthly reports?', 'To view reports: 1) Go to Reports section 2) Select Daily, Weekly, or Monthly view 3) Choose date range 4) View detailed analytics and charts', '', '', '', 1, 1, 1, 0, 1, NULL, '2025-09-25 10:13:00', '2026-02-14 13:25:54'),
(5, 3, 'How to manage categories?', 'To manage categories: 1) Go to Settings 2) Tap Categories 3) Add new categories or edit existing ones 4) Set category icons and colors', '', '', '', 0, 1, 0, 0, 2, NULL, '2025-09-25 10:13:00', '2026-02-14 13:27:09'),
(6, 4, 'How to set up App Lock with PIN?', 'To set up App Lock: 1) Go to Settings 2) Tap Security 3) Enable App Lock 4) Set your 4-digit PIN 5) Confirm PIN to activate', '', '', '', 0, 1, 0, 0, 1, NULL, '2025-09-25 10:13:01', '2026-02-14 13:26:21'),
(7, 4, 'How to change mobile number?', 'To change mobile number: 1) Go to Profile 2) Tap Edit Profile 3) Change mobile number 4) Verify with OTP 5) Save changes', 'https://www.youtube.com/watch?v=sample7', 'https://img.youtube.com/vi/sample7/maxresdefault.jpg', 'sample7', 0, 1, 1, 0, 2, NULL, '2025-09-25 10:13:01', '2026-02-14 13:26:40'),
(8, 5, 'How to backup my data?', 'To backup data: 1) Go to Settings 2) Tap Backup & Restore 3) Select Backup Now 4) Choose backup location 5) Confirm backup', 'https://www.youtube.com/watch?v=sample8', 'https://img.youtube.com/vi/sample8/maxresdefault.jpg', 'sample8', 0, 1, 1, 0, 1, NULL, '2025-09-25 10:13:01', '2026-02-14 13:26:36'),
(9, 5, 'How to export data to Excel/PDF?', 'To export data: 1) Go to Reports 2) Select Export 3) Choose Excel or PDF format 4) Select date range 5) Download file', '', '', '', 1, 1, 0, 0, 2, NULL, '2025-09-25 10:13:01', '2025-12-11 05:27:38'),
(10, 1, 'test 1', 'test', '', '', '', 1, 1, 1, 0, 1, NULL, '2025-09-25 10:13:51', '2025-09-25 10:15:45'),
(11, 1, 'testy', 'test', '', '', '', 0, 1, 1, 0, 1, NULL, '2025-09-25 10:21:23', '2025-09-25 10:21:35'),
(12, 1, 'Test', 'Test', '', '', '', 0, 1, 1, 0, 1, NULL, '2025-09-26 10:33:00', '2025-12-11 05:28:01'),
(13, 2, 'How to edit profile', 'Go to profile then change details', '', '', '', 0, 1, 0, 0, 1, NULL, '2025-09-27 18:52:01', '2026-02-14 13:26:06'),
(14, 5, 'Testing vv', 'Vivo Mobile Name: Vivo Y500\nDisplay\nThis new 5G smartphone from Vivo has a very strong and powerful display screen. This new 5G smartphone has a 6.67-inch display screen. It features a 1080×2400 pixel LCD display and a 144Hz refresh rate.\n\nCamera\nSpeaking of the camera on this new Vivo 5G smartphone, it’s quite impressive. This new 5G smartphone features a 200MP + 18MP + 6MP camera, allowing for high-quality photos and video recording. The front camera is even better, allowing for high-quality selfies. The front camera is 43MP.\n\nBattery\nSpeaking of the battery on this new Vivo 5G smartphone, it’s quite powerful. This new 5G smartphone features a 6000mAh battery, which offers long-lasting performance and supports fast charging. A 220W charger is provided to charge this new Vivo 5G smartphone.\n\nMemory\nSpeaking of memory, Vivo has provided quite ', 'https://youtu.be/SuoXS9NwjYk?si=d-HpudW7TZGz_Smp', 'https://img.youtube.com/vi/SuoXS9NwjYk/maxresdefault.jpg', 'SuoXS9NwjYk', 0, 1, 1, 0, 1, NULL, '2025-09-27 18:58:49', '2025-12-11 05:27:47'),
(15, 2, 'Is it free?', 'Yes, basic features are free. Premium features are available with a paid plan.', '', '', '', 0, 1, 0, 0, 1, NULL, '2026-02-14 13:29:27', '2026-02-14 13:29:27'),
(16, 2, 'Is my data safe?', 'Yes. Your data is secure and backed up safely.', '', '', '', 0, 1, 0, 0, 2, NULL, '2026-02-14 13:30:22', '2026-02-14 13:30:22'),
(17, 3, 'Can I use it for multiple businesses ?', 'Yes, you can manage multiple businesses in one app', '', '', '', 0, 1, 0, 0, 3, NULL, '2026-02-14 13:40:18', '2026-02-14 13:40:18'),
(18, 3, 'Does Premium include automatic backup ?', 'Yes, your data is securely backed up in the cloud.', '', '', '', 0, 1, 0, 0, 4, NULL, '2026-02-14 13:41:15', '2026-02-14 13:41:28'),
(19, 3, 'How do I upgrade to Premium ?', 'Go to Settings → Upgrade to Premium inside the app and choose your plan.', '', '', '', 0, 1, 1, 0, 5, NULL, '2026-02-14 13:42:18', '2026-02-14 13:50:05'),
(20, 3, 'What is Business Health Score ?', 'It shows how strong your business is based on income, expenses, and profit trends — in one simple score.', '', '', '', 0, 1, 1, 0, 6, NULL, '2026-02-14 13:47:48', '2026-02-14 13:49:26'),
(21, 6, 'Can I change the app language ?', 'Yes. Go to Settings → Language and choose your preferred language.', '', '', '', 0, 1, 1, 0, 7, NULL, '2026-02-14 13:48:51', '2026-02-14 13:49:12'),
(22, 9, 'TEST', 'TEST', '', '', '', 1, 1, 1, 0, 1, NULL, '2026-02-14 13:51:49', '2026-04-09 07:41:05'),
(28, 4, 'ewfvewvrevrevfsgrd', 'revrrrevbfbdbfdbfdbf', 'reverevrdbfbdfb', '', '', 0, 1, 1, 0, 1, NULL, '2026-05-27 13:12:33', '2026-05-27 13:12:54');
