INSERT INTO `policy_points` (`point_id`, `category_id`, `point_title`, `point_description`, `point_order`, `is_active`, `created_by`, `created_at`, `updated_at`, `delete_flag`) VALUES
(1, 1, 'Introduction', 'Welcome to Daily Hisab. These terms and conditions govern your use of our financial management application. By using our service, you agree to be bound by these terms.', 1, 1, 1, '2025-09-19 08:44:26', '2025-12-26 10:56:20', 0),
(2, 1, 'User Responsibilities', 'Users must provide accurate information, keep their passwords secure, and use the service in compliance with applicable laws. Users are responsible for all activities that occur under their account.', 2, 1, 1, '2025-09-19 08:44:26', '2025-09-19 08:44:26', 0),
(3, 1, 'Service Availability', 'We strive to maintain high service availability but do not guarantee uninterrupted access. We may perform maintenance, updates, or modifications that temporarily affect service availability.', 3, 1, 1, '2025-09-19 08:44:26', '2025-09-19 08:44:26', 0),
(4, 1, 'Data Security', 'We implement industry-standard security measures to protect your financial data. However, users are responsible for maintaining the security of their login credentials.', 4, 1, 1, '2025-09-19 08:44:26', '2025-09-19 08:44:26', 0),
(5, 1, 'Limitation of Liability', 'Daily Hisab shall not be liable for any indirect, incidental, special, or consequential damages arising from your use of the service.', 5, 1, 1, '2025-09-19 08:44:26', '2025-09-27 08:44:17', 1),
(6, 2, 'Data Collection', 'We collect information you provide directly to us, such as when you create an account, make transactions, or contact us for support. This includes personal and financial information necessary to provide our services. gdsgdfhg', 1, 1, 1, '2025-09-19 08:44:27', '2025-12-08 07:11:38', 0),
(7, 2, 'Data Usage', 'We use your information to provide, maintain, and improve our services, process transactions, communicate with you, and ensure the security of our platform.', 2, 1, 1, '2025-09-19 08:44:27', '2025-09-19 08:44:27', 0),
(8, 2, 'Data Sharing', 'We do not sell, trade, or rent your personal information to third parties. We may share information only as necessary to provide services or as required by law.', 3, 1, 1, '2025-09-19 08:44:27', '2025-09-19 08:44:27', 0),
(9, 2, 'Data Storage', 'Your data is stored securely using encryption and other security measures. We retain your information for as long as necessary to provide services and comply with legal obligations.', 4, 1, 1, '2025-09-19 08:44:27', '2025-09-27 08:48:59', 1),
(10, 2, 'Your Rights', 'You have the right to access, update, or delete your personal information. You can manage your data through your account settings or by contacting us directly.', 5, 1, 1, '2025-09-19 08:44:27', '2025-09-19 08:44:27', 0),
(11, 3, 'Our Mission', 'Our mission is to simplify financial management for individuals and families. We believe everyone deserves easy access to tools that help them understand and control their finances. xvdcvs', 1, 1, 1, '2025-09-19 08:44:27', '2025-12-08 07:11:51', 0),
(12, 3, 'Our Vision', 'We envision a world where financial literacy is accessible to all, and everyone can make informed decisions about their money with confidence and clarity.', 2, 1, 1, '2025-09-19 08:44:27', '2025-09-19 08:44:27', 0),
(13, 3, 'Our Team', 'We are a dedicated team of financial experts, developers, and designers passionate about creating intuitive solutions for personal finance management.', 3, 1, 1, '2025-09-19 08:44:27', '2025-09-19 08:44:27', 0),
(14, 3, 'Our Values', 'We are committed to transparency, security, user privacy, and continuous improvement. These values guide every decision we make in developing our platform.', 4, 1, 1, '2025-09-19 08:44:27', '2025-09-19 08:44:27', 0),
(15, 3, 'Contact Information', 'For questions, support, or feedback, please contact us through our support system or email. We are here to help you succeed in managing your finances.', 5, 1, 1, '2025-09-19 08:44:27', '2025-09-19 08:44:27', 0),
